import { findById } from './users.js';
import { canDelete } from './permissions.js';
import { Cache } from './cache.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

const VALID_TRANSITIONS: Record<Task['status'], Task['status'][]> = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache: Cache = new Cache();

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    // Validate title
    if (!input.title.trim()) {
      throw new Error('Task title must not be empty');
    }

    // Validate user exists
    const user = findById(input.createdBy);
    if (!user) {
      throw new Error(`User ${input.createdBy} does not exist`);
    }

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };

    this.tasks.set(task.id, task);

    // Cache the new task
    this.cache.set(task.id, task, 60000);

    // Audit log
    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      timestamp: Date.now(),
    });

    return task;
  }

  getTask(id: string): Task | null {
    // Check cache first
    const cached = this.cache.get<Task>(id);
    if (cached) return cached;

    const task = this.tasks.get(id) ?? null;
    if (task) {
      this.cache.set(id, task, 60000);
    }
    return task;
  }

  updateStatus(id: string, status: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = VALID_TRANSITIONS[task.status];
    if (!allowed.includes(status)) {
      throw new Error(
        `Invalid status transition from ${task.status} to ${status}`,
      );
    }

    task.status = status;

    // Invalidate cache since task data changed
    this.cache.invalidate(id);

    // Re-cache the updated task
    this.cache.set(id, task, 60000);

    // Audit log
    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      details: `status changed to ${status}`,
      timestamp: Date.now(),
    });

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) return false;

    this.tasks.delete(id);

    // Invalidate cache
    this.cache.invalidate(id);

    // Audit log
    record({
      action: 'delete',
      userId,
      taskId: id,
      timestamp: Date.now(),
    });

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
  }

  clear() {
    this.tasks.clear();
  }
}

export const taskManager = new TaskManager();
