import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('User does not have export permission');
  }

  const tasks = Array.from((taskManager as any).getTask
    ? [taskManager.getTask.bind(taskManager)] // will use list below
    : []);

  // We need to access the internal tasks list - use listByUser approach
  // Actually, we need to iterate all tasks. Let's use a public approach.
  // Since we have full access to the source, we use the internal access via 'any':
  const allTasks = (taskManager as unknown as { [key: string]: unknown })
    .tasks as Map<string, { id: string; title: string; status: string; assignee: string; createdAt: number }>;

  const header = 'id,title,status,assignee,createdAt';
  const rows: string[] = [header];

  for (const task of allTasks.values()) {
    const escapedTitle = /[,"\n]/.test(task.title)
      ? `"${task.title.replace(/"/g, '""')}"`
      : task.title;
    rows.push(
      `${task.id},${escapedTitle},${task.status},${task.assignee},${task.createdAt}`,
    );
  }

  const csv = rows.join('\n');

  // Audit log
  record({
    action: 'export',
    userId,
    details: `Exported ${allTasks.size} tasks`,
    timestamp: Date.now(),
  });

  return csv;
}
", "path": "src/exporter.ts"}

