63	    // Check cache first
64	    const cached = this.cache.get<Task>(id);
65	    if (cached) return cached;
66	
67	    const task = this.tasks.get(id) ?? null;
68	    if (task) {
69	      this.cache.set(id, task, 60000);
70	    }
